def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate a repeated strip: a sequence of colors repeated across
    # adjacent rows or columns.
    sequence = None

    for r in range(h - 1):
        for height in range(2, min(5, h - r) + 1):
            block = grid[r:r + height]
            if all(row == block[0] for row in block[1:]):
                vals = [v for v in block[0] if v]
                if len(vals) >= 3:
                    sequence = vals
                    break
        if sequence:
            break

    if sequence is None:
        for c in range(w - 1):
            for width in range(2, min(5, w - c) + 1):
                block = [row[c:c + width] for row in grid]
                if all(line == block[0] for line in block[1:]):
                    vals = [v for v in block[0] if v]
                    if len(vals) >= 3:
                        sequence = vals
                        break
            if sequence:
                break

    # The template is the connected component of color 1.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            grid[yy][xx] == 1 and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            components.append(component)

    shape = max(components, key=len)
    r0 = min(r for r, c in shape)
    c0 = min(c for r, c in shape)
    offsets = [(r - r0, c - c0) for r, c in shape]
    step = max(dr for dr, dc in offsets) + 1

    out = [[0] * w for _ in range(h)]
    if sequence is None:
        return [row[:] for row in grid]

    center = sequence.index(1)
    for i, color in enumerate(sequence):
        top = r0 + (i - center) * step
        for dr, dc in offsets:
            rr, cc = top + dr, c0 + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
